// Configure the address reachable FROM the n8n container here.
const OLLAMA_BASE_URL = 'http://ollama.host:11434';
const EMBEDDING_MODEL = 'bge-m3:latest';
const MAX_PDF_BYTES = 20 * 1024 * 1024;
const fail = (code, detail) => { throw new Error(`INGEST_${code}|${detail}`); };

const items = $input.all();
if (items.length !== 1) fail(400, 'Bitte genau eine PDF pro Anfrage senden.');
const item = items[0];
const entries = Object.entries(item.binary ?? {});
if (entries.length !== 1 || !['file', 'file0'].includes(entries[0][0])) {
  fail(400, 'Eine PDF im Multipart-Feld file ist erforderlich.');
}
const [key, binary] = entries[0];
const sha256 = item.json.body?.sha256;
// The authenticated backend MUST calculate this hash from the actual PDF bytes.
if (typeof sha256 !== 'string' || !/^[0-9a-f]{64}$/.test(sha256)) {
  fail(400, 'Ein vom Backend berechneter SHA-256-Hash im Feld sha256 ist erforderlich.');
}
const filename = String(binary.fileName || 'document.pdf').split(/[\\/]/).pop();
if (!filename || filename.length > 255 || !/\.pdf$/i.test(filename) || /[\x00-\x1f]/.test(filename)) {
  fail(400, 'Bitte einen gueltigen PDF-Dateinamen verwenden.');
}
const buffer = await this.helpers.getBinaryDataBuffer(0, key);
if (buffer.length === 0) fail(400, 'Die PDF-Datei ist leer.');
if (buffer.length > MAX_PDF_BYTES) fail(413, 'Die PDF ueberschreitet das Limit von 20 MiB.');
if (!buffer.subarray(0, 1024).toString('latin1').includes('%PDF-')) {
  fail(422, 'Die Datei enthaelt keine erkennbare PDF.');
}
return [{
  json: { filename, sha256, embedding_model: EMBEDDING_MODEL,
          ollama_base_url: OLLAMA_BASE_URL.replace(/\/$/, '') },
  binary: { file: binary },
}];

const input = $input.first().json;
const metadata = $('Validate Upload').first().json;
const fail = (code, detail) => { throw new Error(`INGEST_${code}|${detail}`); };
const CHUNK_SIZE = 1000;
const OVERLAP = 200;
const MAX_TEXT_CHARACTERS = 750000;
const MAX_CHUNKS = 1000;
if (typeof input.text !== 'string') fail(422, 'Der PDF-Text konnte nicht gelesen werden.');
const text = input.text.replace(/\u0000/g, '').replace(/\r\n?/g, '\n').trim();
if (!text) fail(422, 'Die PDF enthaelt keinen lesbaren Text. Scans benoetigen OCR.');
if (text.length > MAX_TEXT_CHARACTERS) fail(413, 'Die PDF enthaelt zu viel Text. Bitte in kleinere PDFs aufteilen.');
const chunks = [];
for (let start = 0; start < text.length;) {
  let end = Math.min(start + CHUNK_SIZE, text.length);
  if (end < text.length) {
    // Prefer paragraph/sentence/line boundaries in the last 40% of this window.
    const window = text.slice(start, end);
    for (const separator of ['\n\n', '. ', '! ', '? ', '\n', ' ']) {
      const boundary = window.lastIndexOf(separator);
      if (boundary >= 600) { end = start + boundary + separator.length; break; }
    }
    // Never split a UTF-16 surrogate pair.
    const left = text.charCodeAt(end - 1), right = text.charCodeAt(end);
    if (left >= 0xD800 && left <= 0xDBFF && right >= 0xDC00 && right <= 0xDFFF) end--;
  }
  const content = text.slice(start, end).trim();
  if (content) chunks.push({ index: chunks.length, text: content });
  if (chunks.length > MAX_CHUNKS) fail(413, 'Die PDF erzeugt zu viele Textabschnitte. Bitte aufteilen.');
  if (end >= text.length) break;
  start = end - OVERLAP;
  const code = text.charCodeAt(start);
  if (code >= 0xDC00 && code <= 0xDFFF) start++;
}
if (!chunks.length) fail(422, 'Die PDF enthaelt keine verwertbaren Textabschnitte.');
return [{ json: { ...metadata, chunks } }];

const document = $('Chunk Text').first().json;
const models = $input.first().json.models;
const model = Array.isArray(models) && models.find(m =>
  m.name === document.embedding_model || m.model === document.embedding_model);
if (!model || typeof model.digest !== 'string' || !/^(sha256:)?[0-9a-f]{64}$/.test(model.digest)) {
  throw new Error('INGEST_503|Das konfigurierte Embedding-Modell ist in Ollama nicht verfuegbar.');
}
return [{ json: { ...document, embedding_revision: model.digest } }];

const document = $('Prepare Embeddings').first().json;
const response = $input.first().json;
const vectors = response.embeddings;
const fail = () => { throw new Error('INGEST_503|Der Embedding-Dienst hat unvollstaendige oder ungueltige Vektoren geliefert.'); };
if (response.model !== document.embedding_model || !Array.isArray(vectors) || vectors.length !== document.chunks.length) fail();
for (const vector of vectors) {
  if (!Array.isArray(vector) || vector.length !== 1024 ||
      !vector.every(v => typeof v === 'number' && Number.isFinite(v) && Math.abs(v) <= 3.4028234663852886e38) ||
      !vector.some(v => v !== 0)) fail();
}
return [{ json: { document: {
  sha256: document.sha256,
  filename: document.filename,
  embedding_model: document.embedding_model,
  embedding_revision: document.embedding_revision,
  chunks: document.chunks.map((chunk, index) => ({ ...chunk, embedding: vectors[index] })),
} } }];

const raw = $input.first().json.error;
const message = (typeof raw === 'string' ? raw : (raw?.message ?? '')).replace(/\s*\[line \d+\]\s*$/, '');
const match = message.match(/INGEST_(400|413|422|503)\|([^\n]+)/);
// Do not expose credentials, SQL, internal hostnames, or upstream response bodies.
return [{ json: {
  statusCode: match ? Number(match[1]) : 503,
  body: { detail: match ? match[2] : 'Die Ingestion ist fehlgeschlagen. Bitte erneut versuchen oder die n8n-Konfiguration pruefen.' },
} }];
